51	export const getPublishedNodesForGroups = async ({
52	  client,
53	  currentSpaceId,
54	}: {
55	  client: DGSupabaseClient;
56	  currentSpaceId: number;
57	}): Promise<Array<PublishedNode>> => {
58	  const sharedNodes = await listGroupSharedNodes({
59	    client,
60	    currentSpaceId,
61	  }).catch((error: { message?: string }) => {
62	    console.error("Error fetching published nodes:", error);
63	    throw new Error(`Failed to fetch published nodes: ${error.message}`);
64	  });
65	
66	  return sharedNodes.map((sharedNode) => {
67	    const metadata = sharedNode.directMetadata;
68	    const filePath: string | undefined =
69	      metadata !== null &&
70	      typeof metadata === "object" &&
71	      !Array.isArray(metadata) &&
72	      typeof metadata.filePath === "string"
73	        ? metadata.filePath
74	        : undefined;
75	    return {
76	      source_local_id: sharedNode.sourceLocalId,
77	      space_id: sharedNode.spaceId,
78	      text: sharedNode.title,
79	      createdAt: sharedNode.created
80	        ? new Date(sharedNode.created).valueOf()
81	        : 0,
82	      modifiedAt: new Date(sharedNode.lastModified).valueOf(),
83	      filePath,
84	      authorId: sharedNode.authorId,
85	    };
86	  });
87	};
