89	export const getLocalNodeInstanceIds = (
90	  plugin: DiscourseGraphPlugin,
91	): Set<string> => {
92	  const queryEngine = new QueryEngine(plugin.app);
93	  const files = queryEngine.getFilesWithNodeInstanceId();
94	  const nodeInstanceIds = new Set<string>();
95	
96	  for (const file of files) {
97	    const cache = plugin.app.metadataCache.getFileCache(file);
98	    const frontmatter = cache?.frontmatter;
99	    if (frontmatter?.nodeInstanceId) {
100	      nodeInstanceIds.add(frontmatter.nodeInstanceId as string);
101	    }
102	  }
103	
104	  return nodeInstanceIds;
105	};
