107	/**
108	 * Returns the space name for a given space ID.
109	 * Falls back to "space-{id}" if the lookup fails.
110	 */
111	export const getSpaceNameFromId = async (
112	  client: DGSupabaseClient,
113	  spaceId: number,
114	): Promise<string> => {
115	  const { data, error } = await client
116	    .from("Space")
117	    .select("name")
118	    .eq("id", spaceId)
119	    .maybeSingle();
120	
121	  if (error || !data) {
122	    console.error("Error fetching space name:", error);
123	    return `space-${spaceId}`;
124	  }
125	
126	  return data.name;
127	};
