137	/** Spaces the user cannot see, and rows missing any of the three columns, are absent from the map. */
138	export const getSpaceInfoFromIds = async (
139	  client: DGSupabaseClient,
140	  spaceIds: number[],
141	): Promise<Map<number, SpaceInfo>> => {
142	  if (spaceIds.length === 0) {
143	    return new Map();
144	  }
145	
146	  const { data, error } = await client
147	    .from("my_spaces")
148	    .select("id, name, url, platform")
149	    .in("id", spaceIds);
150	
151	  if (error) {
152	    console.error("Error fetching spaces:", error);
153	    return new Map();
154	  }
155	
156	  const spaceMap = new Map<number, SpaceInfo>();
157	  (data ?? []).forEach(({ id, name, url, platform }) => {
158	    if (id === null || name === null || url === null || platform === null) {
159	      return;
160	    }
161	    spaceMap.set(id, { name, url, platform });
162	  });
163	
164	  return spaceMap;
165	};
