167	export const fetchUserNames = async (
168	  plugin: DiscourseGraphPlugin,
169	  client: DGSupabaseClient,
170	) => {
171	  const result = await client
172	    .from("my_accounts")
173	    .select("id, name")
174	    .eq("agent_type", "person");
175	  if (result.error || !result.data) {
176	    console.error(result.error);
177	    return;
178	  }
179	  const nameById = Object.fromEntries(
180	    result.data.map(({ id, name }) => [id, name]) as [number, string][],
181	  );
