284	type NodeTypeSchemaForInstance = {
285	  nodeTypeId: string;
286	  name: string;
287	};
288	
289	type NodeInstanceImportInfo = {
290	  schema?: NodeTypeSchemaForInstance;
291	  coreTitle?: string;
292	  sourceDocumentId?: number;
293	};
294	
295	export const fetchNodeImportInfoForInstances = async ({
296	  client,
297	  spaceId,
298	  nodeInstanceIds,
299	}: {
300	  client: DGSupabaseClient;
301	  spaceId: number;
302	  nodeInstanceIds: string[];
303	}): Promise<Map<string, NodeInstanceImportInfo>> => {
304	  const result = new Map<string, NodeInstanceImportInfo>();
305	
306	  const { data: instanceRows, error: instanceError } = await client
307	    .from("my_concepts")
308	    .select(
309	      "source_local_id, schema_id, core_title:literal_content->>core_title, sourceDocument:reference_content->sourceDocument",
310	    )
311	    .eq("space_id", spaceId)
312	    .eq("is_schema", false)
313	    .eq("is_relation", false)
314	    .in("source_local_id", nodeInstanceIds);
315	
316	  if (instanceError || !instanceRows) {
317	    console.error("Error fetching node instance concepts:", instanceError);
318	    return result;
319	  }
320	
321	  const schemaIds = [
322	    ...new Set(
323	      instanceRows
324	        .map((row) => row.schema_id)
325	        .filter((id): id is number => id !== null),
326	    ),
327	  ];
328	
329	  const schemasById = new Map<number, NodeTypeSchemaForInstance>();
330	  if (schemaIds.length > 0) {
331	    const { data: schemaRows, error: schemaError } = await client
332	      .from("my_concepts")
333	      .select("id, source_local_id, name")
334	      .eq("space_id", spaceId)
335	      .eq("is_schema", true)
336	      .eq("is_relation", false)
337	      .in("id", schemaIds);
338	
339	    if (schemaError || !schemaRows) {
340	      console.error("Error fetching node type schemas:", schemaError);
341	    } else {
342	      for (const row of schemaRows) {
343	        if (
344	          row.id !== null &&
345	          row.source_local_id !== null &&
346	          row.name !== null
347	        ) {
348	          schemasById.set(row.id, {
349	            nodeTypeId: row.source_local_id,
350	            name: row.name,
351	          });
352	        }
353	      }
354	    }
355	  }
356	
357	  for (const row of instanceRows) {
358	    if (row.source_local_id === null) continue;
359	    result.set(row.source_local_id, {
360	      schema:
361	        row.schema_id === null ? undefined : schemasById.get(row.schema_id),
362	      coreTitle: row.core_title ?? undefined,
363	      sourceDocumentId:
364	        typeof row.sourceDocument === "number" ? row.sourceDocument : undefined,
365	    });
366	  }
367	
368	  return result;
369	};
