451	const downloadFileFromStorage = async ({
452	  client,
453	  filehash,
454	}: {
455	  client: DGSupabaseClient;
456	  filehash: string;
457	}): Promise<ArrayBuffer | null> => {
458	  try {
459	    const { data, error } = await client.storage
460	      .from("assets")
461	      .download(filehash);
462	
463	    if (error) {
464	      return null;
465	    }
