478	/** Normalize path for lookup: strip leading "./", collapse slashes. Shared so pathMapping keys match link paths. */
479	const normalizePathForLookup = (p: string): string =>
480	  p.replace(/^\.\//, "").replace(/\/+/g, "/").trim();
481	
482	const updateMarkdownAssetLinks = ({
483	  content,
484	  oldPathToNewPath,
485	  targetFile,
486	  app,
487	  originalNodePath,
488	}: {
489	  content: string;
490	  oldPathToNewPath: Map<string, string>;
491	  targetFile: TFile;
492	  app: App;
493	  originalNodePath?: string;
494	}): string => {
495	  // Create a set of all new paths for quick lookup (used by findImportedAssetFile when pathMapping has entries)
496	  const newPaths = new Set(oldPathToNewPath.values());
497	
498	  let updatedContent = content;
499	
500	  const noteDir = targetFile.path.includes("/")
501	    ? targetFile.path.replace(/\/[^/]*$/, "")
502	    : "";
503	
504	  // When the note is under import/{spaceName}/, only treat wiki links as resolved if the target is in this folder (not some other vault file).
505	  const pathParts = targetFile.path.split("/");
506	  const importFolder =
507	    pathParts[0] === "import" && pathParts.length >= 2
508	      ? pathParts.slice(0, 2).join("/")
509	      : null;
510	
511	  /** Path of targetFile relative to the current note, for use in links. Obsidian resolves relative links from the note's directory. */
512	  const getRelativeLinkPath = (assetPath: string): string => {
513	    const noteParts = noteDir ? noteDir.split("/").filter(Boolean) : [];
514	    const targetParts = assetPath.split("/").filter(Boolean);
515	    let i = 0;
516	    while (
517	      i < noteParts.length &&
518	      i < targetParts.length &&
519	      noteParts[i] === targetParts[i]
520	    ) {
521	      i++;
522	    }
523	    const ups = noteParts.length - i;
524	    const down = targetParts.slice(i);
525	    const segments = [...Array(ups).fill(".."), ...down];
526	    return segments.join("/");
527	  };
528	
529	  // Resolve a path with ".." and "." segments relative to a base directory (vault-relative).
530	  const resolvePathRelativeToBase = (
531	    baseDir: string,
532	    relativePath: string,
533	  ): string => {
534	    const baseParts = baseDir ? baseDir.split("/").filter(Boolean) : [];
535	    const pathParts = relativePath.replace(/\/+/g, "/").trim().split("/");
536	    const result = [...baseParts];
537	    for (const part of pathParts) {
538	      if (part === "..") {
539	        result.pop();
540	      } else if (part !== "." && part !== "") {
541	        result.push(part);
542	      }
543	    }
544	    return result.join("/");
545	  };
546	
547	  // Canonical form for matching link paths to oldPath (vault-relative, no import prefix).
548	  const getLinkCanonicalForMatch = (linkPath: string): string => {
549	    const resolved = resolvePathRelativeToBase(noteDir, linkPath);
