1141	/**
1142	 * Sanitize each path segment for use under the import folder, preserving the source
1143	 * vault's folder structure.
1144	 *
1145	 * Segments arrive from a `FileReference` row, so they are remote input. The path is
1146	 * normalized rather than filtered: a user may have written it by hand, and existing
1147	 * imports sit at the resolved location, so `a/../b.png` must keep landing on `b.png` or
1148	 * a re-import writes a second copy beside the first.
1149	 *
1150	 * A `..` that would climb past the import folder is dropped instead, which is the escape
1151	 * this exists to stop and the one place it disagrees with the source. A segment that
1152	 * sanitizes away to nothing is dropped too, since an empty segment breaks folder
1153	 * creation. Neither is rejected, so an oddly named asset still imports.
1154	 */
1155	const sanitizePathForImport = (path: string): string => {
1156	  const segments: string[] = [];
1157	  for (const rawSegment of path.split("/")) {
1158	    const segment = sanitizeFileName(rawSegment);
1159	    if (segment === "" || segment === ".") continue;
1160	    if (segment === "..") {
1161	      // Empty stack means this would climb out of the import folder: drop it.
1162	      segments.pop();
1163	      continue;
1164	    }
1165	    segments.push(segment);
1166	  }
1167	  return segments.join("/");
1168	};
