1190	const parseSchemaLiteralContent = (
1191	  literalContent: unknown,
1192	  fallbackName: string,
1193	): Pick<
1194	  DiscourseNode,
1195	  "name" | "format" | "color" | "tag" | "template" | "keyImage"
1196	> & { templateContent?: string } => {
1197	  const obj =
1198	    typeof literalContent === "string"
1199	      ? (JSON.parse(literalContent) as Record<string, unknown>)
1200	      : (literalContent as Record<string, unknown>) || {};
1201	  const src = (obj.source_data as Record<string, unknown>) || obj;
1202	  const name = (obj.name as string) || (obj.label as string) || fallbackName;
1203	  const formatFromSchema =
1204	    (src.format as string) || (obj.format as string) || "";
