1206	    formatFromSchema || `${name.slice(0, 3).toUpperCase()} - {content}`;
1207	  return {
1208	    name,
1209	    format,
1210	    color: (src.color as string) || (obj.color as string) || undefined,
1211	    tag: (src.tag as string) || (obj.tag as string) || undefined,
1212	    template: (obj.template as string) || undefined,
1213	    templateContent: (obj.template_content as string) || undefined,
1214	    keyImage:
1215	      (src.keyImage as boolean) ?? (obj.keyImage as boolean) ?? undefined,
1216	  };
1217	};
