38	/**
39	 * Map a remote relation type to local. Match by id first (use local if id exists with different label/complement),
40	 * then by label, create if new.
41	 */
42	const mapRelationTypeToLocal = async ({
43	  plugin,
44	  client,
45	  sourceSpaceId,
46	  sourceSpaceUri,
47	  sourceRelationTypeId,
48	}: {
49	  plugin: DiscourseGraphPlugin;
50	  client: DGSupabaseClient;
51	  sourceSpaceId: number;
52	  sourceSpaceUri: string;
53	  sourceRelationTypeId: string;
54	}): Promise<string> => {
55	  const { data: schemaData } = await client
56	    .from("my_concepts")
57	    .select("name, literal_content, author_id")
58	    .eq("space_id", sourceSpaceId)
59	    .eq("is_schema", true)
60	    .eq("source_local_id", sourceRelationTypeId)
61	    .maybeSingle();
62	
63	  if (!schemaData?.name) {
64	    return sourceRelationTypeId;
65	  }
66	
67	  const obj =
68	    typeof schemaData.literal_content === "string"
69	      ? (JSON.parse(schemaData.literal_content) as Record<string, unknown>)
70	      : (schemaData.literal_content as Record<string, unknown>) || {};
71	  const label = (obj.label as string) || schemaData.name;
72	  const complement = (obj.complement as string) || "";
73	
74	  // A local match wins even when label/complement differ — local wording is authoritative
75	  const localMatch = findLocalRelationTypeMatch({
76	    localRelationTypes: plugin.settings.relationTypes,
77	    id: sourceRelationTypeId,
78	    label,
79	  });
80	  if (localMatch) {
81	    return localMatch.id;
82	  }
83	
84	  // Create new relation type
85	  const now = new Date().getTime();
86	  const importedFromRid = buildSchemaRid({
87	    spaceUri: sourceSpaceUri,
88	    localId: sourceRelationTypeId,
89	  });
90	
91	  const newRelationType: DiscourseRelationType = {
92	    id: sourceRelationTypeId,
93	    label,
94	    complement,
95	    color: DEFAULT_TLDRAW_COLOR,
96	    created: now,
97	    modified: now,
98	    importedFromRid,
99	    status: "provisional",
100	    authorId: schemaData.author_id ?? undefined,
101	  };
102	  plugin.settings.relationTypes = [
103	    ...(plugin.settings.relationTypes ?? []),
104	    newRelationType,
105	  ];
106	  await plugin.saveSettings();
107	  return newRelationType.id;
108	};
