110	/**
111	 * Find or create a DiscourseRelation (triple) for the given (source node type, dest node type, relation type).
112	 * If one exists with the same three ids, return it; otherwise create a new one and add to settings.
113	 * When creating, uses remote relation instance timestamps and importedFromRid when provided.
114	 */
115	const findOrCreateTriple = async ({
116	  plugin,
117	  sourceNodeTypeId,
118	  destNodeTypeId,
119	  relationTypeId,
120	  importedCreatedAt,
121	  importedModifiedAt,
122	  importedFromRid,
123	  authorId,
124	}: {
125	  plugin: DiscourseGraphPlugin;
126	  sourceNodeTypeId: string;
127	  destNodeTypeId: string;
128	  relationTypeId: string;
129	  importedCreatedAt?: number;
130	  importedModifiedAt?: number;
131	  importedFromRid?: string;
132	  authorId?: number;
133	}): Promise<DiscourseRelation> => {
134	  const existing = findExistingTriple({
135	    discourseRelations: plugin.settings.discourseRelations ?? [],
136	    sourceId: sourceNodeTypeId,
137	    destinationId: destNodeTypeId,
138	    relationshipTypeId: relationTypeId,
139	  });
140	  if (existing) return existing;
141	
142	  const now = Date.now();
143	  const created =
144	    importedCreatedAt != null && !Number.isNaN(importedCreatedAt)
145	      ? importedCreatedAt
146	      : now;
147	  const modified =
148	    importedModifiedAt != null && !Number.isNaN(importedModifiedAt)
149	      ? importedModifiedAt
150	      : now;
151	  const newTriple: DiscourseRelation = {
152	    id: uuidv7(),
153	    sourceId: sourceNodeTypeId,
154	    destinationId: destNodeTypeId,
155	    relationshipTypeId: relationTypeId,
156	    created,
157	    modified,
158	    ...(importedFromRid && { importedFromRid }),
159	    status: "provisional",
160	    authorId,
161	  };
162	  plugin.settings.discourseRelations = [
163	    ...(plugin.settings.discourseRelations ?? []),
164	    newTriple,
165	  ];
166	  await plugin.saveSettings();
167	  return newTriple;
168	};
