258	        (rel.reference_content as Record<string, number | number[]>)
259	          .destination,
260	    );
261	    if (!sourceData || !destData) continue;
262	
263	    const sourceKey = `${sourceData.space_id}:${sourceData.source_local_id}`;
264	    const destKey = `${destData.space_id}:${destData.source_local_id}`;
265	
266	    const sourceEndpointId = keyToRelationEndpointId.get(sourceKey);
267	    const destEndpointId = keyToRelationEndpointId.get(destKey);
268	    if (!sourceEndpointId || !destEndpointId) continue;
269	
270	    if (!rel.schema_id) continue;
271	
272	    const sourceRelationTypeId = schemaMap.get(rel.schema_id);
273	    if (!sourceRelationTypeId) continue;
274	
275	    const mappedTypeId = await mapRelationTypeToLocal({
276	      plugin,
277	      client,
278	      sourceSpaceId: spaceId,
279	      sourceSpaceUri: spaceUri,
280	      sourceRelationTypeId,
281	    });
282	
283	    if (!mappedTypeId) continue;
284	
285	    const { data: conceptSchemas } = await client
286	      .from("my_concepts")
287	      .select("id, schema_id")
288	      .in("id", [sourceData.id, destData.id]);
289	
290	    let mappedSourceNodeTypeId: string | null = null;
291	    let mappedDestNodeTypeId: string | null = null;
292	    if (conceptSchemas && conceptSchemas.length === 2) {
293	      const byConceptId = Object.fromEntries(
294	        (conceptSchemas as Array<{ id: number; schema_id: number | null }>).map(
295	          (r) => [r.id, r.schema_id],
296	        ),
297	      );
298	      const sourceSchemaId = byConceptId[sourceData.id];
299	      const destSchemaId = byConceptId[destData.id];
300	      if (sourceSchemaId != null && destSchemaId != null) {
301	        const uniqueSchemaIds = [...new Set([sourceSchemaId, destSchemaId])];
302	        const { data: schemaRows } = await client
303	          .from("my_concepts")
304	          .select("id, source_local_id")
305	          .in("id", uniqueSchemaIds);
306	        if (schemaRows && schemaRows.length === uniqueSchemaIds.length) {
307	          const schemaIdToLocalId = Object.fromEntries(
308	            (schemaRows as Array<{ id: number; source_local_id: string }>).map(
309	              (row) => [row.id, row.source_local_id],
310	            ),
311	          );
312	          const remoteSourceNodeTypeId = schemaIdToLocalId[sourceSchemaId];
313	          const remoteDestNodeTypeId = schemaIdToLocalId[destSchemaId];
314	          if (remoteSourceNodeTypeId && remoteDestNodeTypeId) {
315	            mappedSourceNodeTypeId = await mapNodeTypeIdToLocal({
316	              plugin,
317	              client,
