326	              sourceSpaceUri: spaceUri,
327	              sourceNodeTypeId: remoteDestNodeTypeId,
328	            });
329	          }
330	        }
331	      }
332	    }
333	    const relationImportedFromRid =
334	      rel.source_local_id != null && rel.source_local_id !== ""
335	        ? spaceUriAndLocalIdToRid(spaceUri, rel.source_local_id, "relation")
