337	    const importedCreatedAt =
338	      rel.created != null
339	        ? new Date(
340	            rel.created + (rel.created.endsWith("Z") ? "" : "Z"),
341	          ).getTime()
342	        : undefined;
343	    const importedModifiedAt =
344	      rel.last_modified != null
345	        ? new Date(
346	            rel.last_modified + (rel.last_modified.endsWith("Z") ? "" : "Z"),
347	          ).getTime()
348	        : undefined;
349	
350	    const authorId = rel.author_id ?? undefined;
351	    if (mappedSourceNodeTypeId && mappedDestNodeTypeId) {
352	      await findOrCreateTriple({
353	        plugin,
354	        sourceNodeTypeId: mappedSourceNodeTypeId,
355	        destNodeTypeId: mappedDestNodeTypeId,
356	        relationTypeId: mappedTypeId,
357	        importedCreatedAt,
358	        importedModifiedAt,
359	        importedFromRid: relationImportedFromRid,
360	        authorId,
361	      });
362	    }
363	
364	    const existing = findRelationBySourceDestinationType(
365	      relationsData,
366	      sourceEndpointId,
367	      destEndpointId,
368	      mappedTypeId,
369	    );
370	    if (existing) continue;
371	
372	    await addRelationNoCheck(plugin, {
373	      type: mappedTypeId,
374	      source: sourceEndpointId,
375	      destination: destEndpointId,
376	      importedFromRid: relationImportedFromRid,
377	      tentative: false,
378	      authorId,
379	    });
380	    imported++;
381	
382	    // Reload relations after each add so findRelationBySourceDestinationType sees new data
383	    Object.assign(relationsData, await loadRelations(plugin));
384	  }
385	
386	  return { imported };
387	};
